require_once BASE_PATH.'/app/config/conexion.php';require_once BASE_PATH.'/app/models/agenda_modelo.php';require_once BASE_PATH.'/app/views/shared/componentes.php';
$u=exigir_usuario(['admin']);$q=$conexion->prepare('SELECT * FROM consultorios WHERE id=?');$q->execute([(int)($_GET['id']??0)]);$sala=$q->fetch();
abrir_pagina('Consultorios');encabezado_gestion('Espacios para la atención','Gestiona consultorios y consulta la ocupación física.',true);ver_aviso();
?>
<div class="gestion-dos-columnas"><section class="gestion-tarjeta"><h2><?= $sala?'Editar consultorio':'Nuevo consultorio' ?></h2><form method="post" action="agenda_acciones.php" class="form-gestion"><?php campo_csrf();?><input type="hidden" name="accion" value="consultorio"><input type="hidden" name="id" value="<?= (int)($sala['id']??0) ?>"><label>Nombre<input name="nombre" minlength="3" maxlength="80" value="<?= e($sala['nombre']??'') ?>" required></label><label>Ubicación<input name="ubicacion" minlength="3" maxlength="120" value="<?= e($sala['ubicacion']??'') ?>" required></label><label class="checkbox-inline"><input type="checkbox" name="activo" <?= !$sala||$sala['activo']?'checked':'' ?>> Habilitado</label><button class="boton boton-primario">Guardar consultorio</button></form><p><a href="consultorios.php">Registrar otro espacio</a></p><p class="texto-ayuda">Asigna el consultorio predeterminado desde <a href="admin_medicos.php">Médicos y horarios</a>. El cambio se usa en nuevas reservas; las citas existentes conservan su espacio. Un mismo consultorio puede compartirse si los horarios no se cruzan.</p></section><section class="gestion-tarjeta"><h2>Consultorios registrados</h2><?php foreach($conexion->query('SELECT s.*,COUNT(m.id) profesionales FROM consultorios s LEFT JOIN medicos m ON m.consultorio_id=s.id GROUP BY s.id ORDER BY s.nombre') as $s):?><article class="proximo-horario"><div><strong><?= e($s['nombre']) ?></strong><p><?= e($s['ubicacion']) ?> · <?= $s['activo']?'Habilitado':'Inactivo' ?><br><?= (int)$s['profesionales'] ?> <?= (int)$s['profesionales']===1?'profesional asignado':'profesionales asignados' ?></p></div><a href="?id=<?= $s['id'] ?>">Editar</a></article><?php endforeach ?></section></div>
<?php $fecha=texto_get_integral('fecha',date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$fecha))$fecha=date('Y-m-d');?><section class="gestion-tarjeta"><h2>Ocupación por fecha</h2><form class="gestion-filtros"><label>Fecha<input type="date" name="fecha" value="<?= e($fecha) ?>" required></label><button class="boton boton-secundario">Consultar</button></form><?php $q=$conexion->prepare("SELECT c.id,c.hora_cita,c.duracion,s.nombre,m.nombres FROM citas c JOIN consultorios s ON s.id=c.consultorio_id JOIN medicos m ON m.id=c.medico_id WHERE c.fecha_cita=? AND c.estado NOT IN('cancelado','rechazado') ORDER BY s.nombre,c.hora_cita");$q->execute([$fecha]);$ocupacion=$q->fetchAll();if(!$ocupacion):?><p>No hay reservas de consultorios para esta fecha.</p><?php endif;foreach($ocupacion as $c):?><p><strong><?= e($c['nombre']) ?> · <?= e(substr($c['hora_cita'],0,5)) ?></strong> · <?= e($c['nombres']) ?> · <a href="comprobante.php?id=<?= $c['id'] ?>"><?= e(codigo_cita($c['id'])) ?></a></p><?php endforeach ?></section><?php cerrar_pagina(); ?>
